            $clobTokenIds = $this->safe_value($marketInfo, 'clobTokenIds', array());
            $assetId = $this->safe_string_2($params, 'asset_id', 'token_id'); // Support both for backward compatibility
            // If asset_id not provided, use first token ID from $market
