    public function handle_order_book(Client $client, $message) {
        //
        // Market websocket order book event:
        //     {
        //         "event_type" => "book",
        //         "asset_id" => "0x...",
        //         "bids" => [[$price, $size], ...],
        //         "asks" => [[$price, $size], ...],
        //         "timestamp" => 1234567890
        //     }
        //
        // Or array of events:
        //     [array(...), array(...)]
        //
        $messages = array();
        if ((gettype($message) === 'array' && array_keys($message) === array_keys(array_keys($message)))) {
            $messages = $message;
        } else {
            $messages = array( $message );
        }
        for ($i = 0; $i < count($messages); $i++) {
            $msg = $messages[$i];
            $eventType = $this->safe_string($msg, 'event_type');
            if ($eventType !== 'book') {
                continue;
            }
            $assetId = $this->safe_string($msg, 'asset_id');
            // Find $symbol and asset_id from subscriptions
            $symbol = null;
            $subscriptionAssetId = null;
            $subscriptionKeys = is_array($client->subscriptions) ? array_keys($client->subscriptions) : array();
            for ($j = 0; $j < count($subscriptionKeys); $j++) {
                $subscribeHash = $subscriptionKeys[$j];
                $subscription = $client->subscriptions[$subscribeHash];
                if ($subscription != null) {
                    $subAssetId = $this->safe_string_2($subscription, 'asset_id', 'token_id'); // Support both for backward compatibility
                    if ($subAssetId === $assetId) {
                        $symbol = $this->safe_string($subscription, 'symbol');
                        $subscriptionAssetId = $subAssetId;
                        break;
                    }
                }
            }
            if ($symbol === null) {
                // Try to resolve from asset_id
                $market = $this->safe_market($assetId);
                $symbol = $market['symbol'];
                $subscriptionAssetId = $assetId;
            }
            $messageHash = 'orderbook:' . $symbol . ':' . $subscriptionAssetId;
            if (!(is_array($this->orderbooks) && array_key_exists($symbol, $this->orderbooks))) {
                $this->orderbooks[$symbol] = $this->order_book(array());
            }
            $orderbook = $this->orderbooks[$symbol];
            // Polymarket docs use `buys`/`sells` with OrderSummary objects, but some payloads use `$bids`/`$asks`
            $rawBids = $this->safe_value_2($msg, 'bids', 'buys', array());
            $rawAsks = $this->safe_value_2($msg, 'asks', 'sells', array());
            $bids = array();
            $bidLevels = $this->to_array($rawBids);
            for ($j = 0; $j < count($bidLevels); $j++) {
                $level = $bidLevels[$j];
                if ((gettype($level) === 'array' && array_keys($level) === array_keys(array_keys($level)))) {
                    $bids[] = $level;
                } elseif (gettype($level) === 'array') {
                    $price = $this->safe_string($level, 'price');
                    $size = $this->safe_string($level, 'size');
                    if ($price !== null && $size !== null) {
                        $bids[] = array( $price, $size );
                    }
                }
            }
            $asks = array();
            $askLevels = $this->to_array($rawAsks);
            for ($j = 0; $j < count($askLevels); $j++) {
                $level = $askLevels[$j];
                if ((gettype($level) === 'array' && array_keys($level) === array_keys(array_keys($level)))) {
                    $asks[] = $level;
                } elseif (gettype($level) === 'array') {
                    $price = $this->safe_string($level, 'price');
                    $size = $this->safe_string($level, 'size');
                    if ($price !== null && $size !== null) {
                        $asks[] = array( $price, $size );
                    }
                }
            }
            $rawTimestamp = $this->safe_integer($msg, 'timestamp');
            $timestamp = null;
            if ($rawTimestamp !== null) {
                if ($rawTimestamp > 1000000000000) {
                    $timestamp = $rawTimestamp;
                } else {
                    $timestamp = $rawTimestamp * 1000;
                }
            }
            $datetime = null;
            if ($timestamp !== null) {
                $datetime = $this->iso8601($timestamp);
            }
            $snapshot = $this->parse_order_book(array( 'bids' => $bids, 'asks' => $asks ), $symbol, $timestamp);
            $orderbook->reset ($snapshot);
            $orderbook['symbol'] = $symbol;
            $orderbook['timestamp'] = $timestamp;
            $orderbook['datetime'] = $datetime;
            $client->resolve ($orderbook, $messageHash);
        }
    }

    public function handle_price_change_order_book(Client $client, $message) {
        //
        // Market websocket price_change event for $orderbook updates:
        //     {
        //         "event_type" => "price_change",
        //         "market" => "0x...",
        //         "price_changes" => array(
        //             {
        //                 "asset_id" => "0x...",
        //                 "price" => "0.5",
        //                 "size" => "200",
        //                 "side" => "BUY",
        //                 "hash" => "0x...",
        //                 "best_bid" => "0.5",
        //                 "best_ask" => "1"
        //             }
        //         ),
        //         "timestamp" => "1757908892351"
        //     }
        //
        // Docs => https://docs.polymarket.com/developers/CLOB/websocket/market-channel#$price-change-$message
        //
        $messages = array();
        if ((gettype($message) === 'array' && array_keys($message) === array_keys(array_keys($message)))) {
            $messages = $message;
        } else {
            $messages = array( $message );
        }
        for ($i = 0; $i < count($messages); $i++) {
            $msg = $messages[$i];
            $eventType = $this->safe_string($msg, 'event_type');
            if ($eventType !== 'price_change') {
                continue;
            }
            $priceChanges = $this->safe_value($msg, 'price_changes', array());
            if ((gettype($priceChanges) !== 'array' || array_keys($priceChanges) !== array_keys(array_keys($priceChanges))) || strlen($priceChanges) === 0) {
                continue;
            }
            $rawTimestamp = $this->safe_integer($msg, 'timestamp');
            $timestamp = null;
            if ($rawTimestamp !== null) {
                if ($rawTimestamp > 1000000000000) {
                    $timestamp = $rawTimestamp;
                } else {
                    $timestamp = $rawTimestamp * 1000;
                }
            }
            // Process each $price change
            for ($k = 0; $k < count($priceChanges); $k++) {
                $priceChange = $priceChanges[$k];
                $assetId = $this->safe_string($priceChange, 'asset_id');
                if ($assetId === null) {
                    continue;
                }
                // Find $symbol and asset_id from subscriptions
                $symbol = null;
                $subscriptionAssetId = null;
                $subscriptionKeys = is_array($client->subscriptions) ? array_keys($client->subscriptions) : array();
                for ($j = 0; $j < count($subscriptionKeys); $j++) {
                    $subscribeHash = $subscriptionKeys[$j];
                    $subscription = $client->subscriptions[$subscribeHash];
                    if ($subscription != null) {
                        $subAssetId = $this->safe_string_2($subscription, 'asset_id', 'token_id');
                        if ($subAssetId === $assetId) {
                            $symbol = $this->safe_string($subscription, 'symbol');
                            $subscriptionAssetId = $subAssetId;
                            break;
                        }
                    }
                }
                if ($symbol === null) {
                    // Try to resolve from asset_id
                    $market = $this->safe_market($assetId);
                    $symbol = $market['symbol'];
                    $subscriptionAssetId = $assetId;
                }
                $messageHash = 'orderbook:' . $symbol . ':' . $subscriptionAssetId;
                // Get or create $orderbook
                if (!(is_array($this->orderbooks) && array_key_exists($symbol, $this->orderbooks))) {
                    $this->orderbooks[$symbol] = $this->order_book(array());
                }
                $orderbook = $this->orderbooks[$symbol];
                // Get $price and $size from $price change
                $price = $this->safe_string($priceChange, 'price');
                $size = $this->safe_string($priceChange, 'size');
                $side = strtoupper($this->safe_string($priceChange, 'side', ''));
                if ($price === null) {
                    continue;
                }
                // Convert $size to number for comparison
                $sizeNum = $this->safe_number($priceChange, 'size', 0);
                // Update $orderbook $side based on $side field
                if ($side === 'BUY') {
                    // Update bids $side
                    if ($sizeNum === 0) {
                        // Remove $price level if $size is 0
                        $orderbook['bids'].storeArray (array( $price, '0' ));
                    } else {
                        // Update or add $price level
                        $orderbook['bids'].storeArray (array( $price, $size ));
                    }
                } elseif ($side === 'SELL') {
                    // Update asks $side
                    if ($sizeNum === 0) {
                        // Remove $price level if $size is 0
                        $orderbook['asks'].storeArray (array( $price, '0' ));
                    } else {
                        // Update or add $price level
                        $orderbook['asks'].storeArray (array( $price, $size ));
                    }
                }
                // Update $timestamp
                if ($timestamp !== null) {
                    $orderbook['timestamp'] = $timestamp;
                    $orderbook['datetime'] = $this->iso8601($timestamp);
                }
                $orderbook['symbol'] = $symbol;
                $client->resolve ($orderbook, $messageHash);
            }
        }
    }

    public function handle_trades(Client $client, $message) {
        //
        // Market websocket $trade event:
        //     {
        //         "event_type" => "trade",
        //         "asset_id" => "0x...",
        //         "trade_id" => "0x...",
        //         "price" => "0.5",
        //         "size" => "100",
        //         "side" => "buy",
        //         "timestamp" => 1234567890
        //     }
        //
        $messages = array();
        if ((gettype($message) === 'array' && array_keys($message) === array_keys(array_keys($message)))) {
            $messages = $message;
        } else {
            $messages = array( $message );
        }
        for ($i = 0; $i < count($messages); $i++) {
            $msg = $messages[$i];
            $eventType = $this->safe_string($msg, 'event_type');
            if ($eventType !== 'trade') {
                continue;
            }
            $assetId = $this->safe_string($msg, 'asset_id');
            // Find $symbol and asset_id from subscriptions
            $symbol = null;
            $subscriptionAssetId = null;
            $subscriptionKeys = is_array($client->subscriptions) ? array_keys($client->subscriptions) : array();
            for ($j = 0; $j < count($subscriptionKeys); $j++) {
                $subscribeHash = $subscriptionKeys[$j];
                $subscription = $client->subscriptions[$subscribeHash];
                if (gettype($subscription) === 'array') {
                    $subAssetId = $this->safe_string_2($subscription, 'asset_id', 'token_id'); // Support both for backward compatibility
                    if ($subAssetId === $assetId) {
                        $symbol = $this->safe_string($subscription, 'symbol');
                        $subscriptionAssetId = $subAssetId;
                        break;
                    }
                }
            }
            if ($symbol === null) {
                // Try to resolve from asset_id
                $market = $this->safe_market($assetId);
                $symbol = $market['symbol'];
                $subscriptionAssetId = $assetId;
            }
            $messageHash = 'trades:' . $symbol . ':' . $subscriptionAssetId;
            $stored = $this->safe_value($this->trades, $symbol);
            if ($stored === null) {
                $limit = $this->safe_integer($this->options, 'tradesLimit', 1000);
                $stored = new ArrayCache ($limit);
                $this->trades[$symbol] = $stored;
            }
            $market = $this->market($symbol);
            $trade = $this->parse_trade($msg, $market);
            // Normalize WS timestamp (Polymarket typically sends ms timestamps in WS payloads)
            $rawTimestamp = $this->safe_integer($msg, 'timestamp');
            $wsTimestamp = null;
            if ($rawTimestamp !== null) {
                if ($rawTimestamp > 1000000000000) {
                    $wsTimestamp = $rawTimestamp;
                } else {
                    $wsTimestamp = $rawTimestamp * 1000;
                }
            }
            if ($wsTimestamp !== null) {
                $trade['timestamp'] = $wsTimestamp;
                $trade['datetime'] = $this->iso8601($wsTimestamp);
            }
            $stored->append ($trade);
            $client->resolve ($stored, $messageHash);
        }
    }

    public function handle_ticker(Client $client, $message) {
        //
        // Market websocket $ticker events:
        //     {
        //         "event_type" => "price_change",
        //         "asset_id" => "0x...",
        //         "price" => "0.5",
        //         "timestamp" => 1234567890
        //     }
        //     {
        //         "event_type" => "last_trade_price",
        //         "asset_id" => "0x...",
        //         "price" => "0.5",
        //         "timestamp" => 1234567890
        //     }
        //
        $messages = array();
        if ((gettype($message) === 'array' && array_keys($message) === array_keys(array_keys($message)))) {
            $messages = $message;
        } else {
            $messages = array( $message );
        }
        for ($i = 0; $i < count($messages); $i++) {
            $msg = $messages[$i];
            $eventType = $this->safe_string($msg, 'event_type');
            if ($eventType !== 'price_change' && $eventType !== 'last_trade_price') {
                continue;
            }
            // `last_trade_price` is per-asset, but `price_change` can be a batch containing `price_changesarray()`.
            // Docs => https://docs.polymarket.com/developers/CLOB/websocket/market-channel#price-change-$message
            $rawTimestamp = $this->safe_integer($msg, 'timestamp');
            $timestamp = null;
            if ($rawTimestamp !== null) {
                if ($rawTimestamp > 1000000000000) {
                    $timestamp = $rawTimestamp;
                } else {
                    $timestamp = $rawTimestamp * 1000;
                }
            }
            $priceChanges = $this->safe_value($msg, 'price_changes');
            $updates => anyarray() = array();
            if ($eventType === 'price_change' && (gettype($priceChanges) === 'array' && array_keys($priceChanges) === array_keys(array_keys($priceChanges)))) {
                $updates = $priceChanges;
            } else {
                $updates = array( $msg );
            }
            for ($k = 0; $k < count($updates); $k++) {
                $update = $updates[$k];
                $assetId = $this->safe_string($update, 'asset_id', $this->safe_string($msg, 'asset_id'));
                if ($assetId === null) {
                    continue;
                }
                // Find $symbol and asset_id from subscriptions
                $symbol = null;
                $subscriptionAssetId = null;
                $subscriptionKeys = is_array($client->subscriptions) ? array_keys($client->subscriptions) : array();
                for ($j = 0; $j < count($subscriptionKeys); $j++) {
                    $subscribeHash = $subscriptionKeys[$j];
                    $subscription = $client->subscriptions[$subscribeHash];
                    if (gettype($subscription) === 'array') {
                        $subAssetId = $this->safe_string_2($subscription, 'asset_id', 'token_id'); // Support both for backward compatibility
                        if ($subAssetId === $assetId) {
                            $symbol = $this->safe_string($subscription, 'symbol');
                            $subscriptionAssetId = $subAssetId;
                            break;
                        }
                    }
                }
                if ($symbol === null) {
                    // Try to resolve from asset_id
                    $market = $this->safe_market($assetId);
                    $symbol = $market['symbol'];
                    $subscriptionAssetId = $assetId;
                }
                $messageHash = 'ticker:' . $symbol . ':' . $subscriptionAssetId;
                $market = $this->market($symbol);
                $prev = $this->safe_value($this->tickers, $symbol, array());
                $last = $this->safe_number($update, 'price', $this->safe_number($msg, 'price', $this->safe_number($prev, 'last')));
                $bid = $this->safe_number($update, 'best_bid', $this->safe_number($prev, 'bid', $last));
                $ask = $this->safe_number($update, 'best_ask', $this->safe_number($prev, 'ask', $last));
                $info = $msg;
                if ($eventType === 'price_change') {
                    $info = $update;
                }
                $datetime = null;
                if ($timestamp !== null) {
                    $datetime = $this->iso8601($timestamp);
                }
                $ticker => Ticker = array(
                    'symbol' => $symbol,
                    'info' => $info,
                    'timestamp' => $timestamp,
                    'datetime' => $datetime,
                    'last' => $last,
                    'bid' => $bid,
                    'bidVolume' => null,
                    'ask' => $ask,
                    'askVolume' => null,
                    'high' => null,
                    'low' => null,
                    'open' => null,
                    'close' => $last,
                    'previousClose' => null,
                    'change' => null,
                    'percentage' => null,
                    'average' => null,
                    'baseVolume' => null,
                    'quoteVolume' => null,
                    'vwap' => null,
                    'indexPrice' => null,
                    'markPrice' => null,
                );
                $this->tickers[$symbol] = $ticker;
                $client->resolve ($ticker, $messageHash);
            }
        }
    }

    public function handle_orders(Client $client, $message) {
        //
        // User websocket $order event:
        //     {
        //         "event_type" => "order",
        //         "order_id" => "0x...",
        //         "asset_id" => "0x...",
        //         "side" => "buy",
        //         "price" => "0.5",
        //         "size" => "100",
        //         "status" => "open",
        //         "timestamp" => 1234567890
        //     }
        //
        $eventType = $this->safe_string($message, 'event_type');
        if ($eventType !== 'order') {
            return;
        }
        $messageHash = 'orders';
        $stored = $this->orders;
        if ($stored === null) {
            $limit = $this->safe_integer($this->options, 'ordersLimit', 1000);
            $stored = new ArrayCacheBySymbolById ($limit);
            $this->orders = $stored;
        }
        $order = $this->parse_order($message);
        $rawTimestamp = $this->safe_integer($message, 'timestamp');
        $wsTimestamp = null;
        if ($rawTimestamp !== null) {
            if ($rawTimestamp > 1000000000000) {
                $wsTimestamp = $rawTimestamp;
            } else {
                $wsTimestamp = $rawTimestamp * 1000;
            }
        }
        if ($wsTimestamp !== null) {
            $order['timestamp'] = $wsTimestamp;
            $order['datetime'] = $this->iso8601($wsTimestamp);
        }
        $orderSymbols = array();
        $orderSymbols[$order['symbol']] = true;
        $stored->append ($order);
        $unique = is_array($orderSymbols) ? array_keys($orderSymbols) : array();
        for ($i = 0; $i < count($unique); $i++) {
            $symbol = $unique[$i];
            $symbolSpecificMessageHash = $messageHash . ':' . $symbol;
            $client->resolve ($stored, $symbolSpecificMessageHash);
        }
        $client->resolve ($stored, $messageHash);
    }

    public function handle_my_trades(Client $client, $message) {
        //
        // User websocket $trade event:
        //     {
        //         "event_type" => "trade",
        //         "trade_id" => "0x...",
        //         "asset_id" => "0x...",
        //         "side" => "buy",
        //         "price" => "0.5",
        //         "size" => "100",
        //         "timestamp" => 1234567890
        //     }
        //
        $eventType = $this->safe_string($message, 'event_type');
        if ($eventType !== 'trade') {
            return;
        }
        $messageHash = 'myTrades';
        $stored = $this->myTrades;
        if ($stored === null) {
            $limit = $this->safe_integer($this->options, 'tradesLimit', 1000);
            $stored = new ArrayCacheBySymbolById ($limit);
            $this->myTrades = $stored;
        }
        $trade = $this->parse_trade($message);
        $rawTimestamp = $this->safe_integer($message, 'timestamp');
        $wsTimestamp = null;
        if ($rawTimestamp !== null) {
            if ($rawTimestamp > 1000000000000) {
                $wsTimestamp = $rawTimestamp;
            } else {
                $wsTimestamp = $rawTimestamp * 1000;
            }
        }
        if ($wsTimestamp !== null) {
            $trade['timestamp'] = $wsTimestamp;
            $trade['datetime'] = $this->iso8601($wsTimestamp);
        }
        $tradeSymbols = array();
        $tradeSymbols[$trade['symbol']] = true;
        $stored->append ($trade);
        $unique = is_array($tradeSymbols) ? array_keys($tradeSymbols) : array();
        $uniqueLength = count($unique);
        if ($uniqueLength === 0) {
            return;
        }
        for ($i = 0; $i < count($unique); $i++) {
            $symbol = $unique[$i];
            $symbolSpecificMessageHash = $messageHash . ':' . $symbol;
            $client->resolve ($stored, $symbolSpecificMessageHash);
        }
        $client->resolve ($stored, $messageHash);
    }

    public function handle_message(Client $client, $message) {
        //
        // Market websocket messages can be:
        //     - Single $event object => array("event_type" => "book", ...)
        //     - Array of events => [array("event_type" => "book", ...), ...]
        //     - Ready $event => array("event" => "ready") or similar (check Python code)
        //
        // User websocket messages:
        //     - Single $event object => array("event_type" => "order", ...)
        //
        // Check for ready $event first (Polymarket may send this)
        $event = $this->safe_string($message, 'event');
        if ($event === 'ready' || $event === 'connected') {
            // Connection ready - subscriptions are sent automatically by base watch() method
            return;
        }
        if ((gettype($message) === 'array' && array_keys($message) === array_keys(array_keys($message)))) {
            // Handle array of events (market websocket)
            $this->handle_market_events($client, $message);
        } else {
            $eventType = $this->safe_string($message, 'event_type');
            $url = $client->url;
            // Determine which websocket based on URL
            if (mb_strpos($url, '/ws/market') !== false) {
                // Market websocket
                $this->handle_market_event($client, $message, $eventType);
            } elseif (mb_strpos($url, '/ws/user') !== false) {
                // User websocket
                $this->handle_user_event($client, $message, $eventType);
            } elseif (mb_strpos($url, 'ws-live-data') !== false) {
                // Live data websocket - not implemented yet
                if ($this->verbose) {
                    $this->log('Live data websocket $message:', $message);
                }
            }
        }
    }

    public function handle_market_events(Client $client, array $messages) {
        // Handle array of market events
        for ($i = 0; $i < count($messages); $i++) {
            $msg = $messages[$i];
            $eventType = $this->safe_string($msg, 'event_type');
            $this->handle_market_event($client, $msg, $eventType);
        }
    }

    public function handle_market_event(Client $client, mixed $message, string $eventType) {
        if ($eventType === 'book') {
            $this->handle_order_book($client, $message);
        } elseif ($eventType === 'trade') {
            $this->handle_trades($client, $message);
        } elseif ($eventType === 'price_change') {
            // price_change updates both orderbook and ticker
            $this->handle_price_change_order_book($client, $message);
            $this->handle_ticker($client, $message);
        } elseif ($eventType === 'last_trade_price') {
            $this->handle_ticker($client, $message);
        } elseif ($eventType === 'tick_size_change') {
            // Tick size change - can be used to update ticker
            if ($this->verbose) {
                $this->log('Tick size change event:', $message);
            }
        } elseif ($eventType === 'new_market') {
            $marketsSubscription = $this->safe_value($client->subscriptions, 'markets');
            $customFeatureEnabled = $marketsSubscription ? $this->safe_bool($marketsSubscription, 'custom_feature_enabled', false) : false;
            if ($customFeatureEnabled) {
                $this->handle_new_market($client, $message);
            }
        } elseif ($eventType === 'market_resolved') {
            $marketsSubscription = $this->safe_value($client->subscriptions, 'markets');
            $customFeatureEnabled = $marketsSubscription ? $this->safe_bool($marketsSubscription, 'custom_feature_enabled', false) : false;
            if ($customFeatureEnabled) {
                $this->handle_market_resolved($client, $message);
            }
        } else {
            // Unknown event type, log but don't error
            if ($this->verbose) {
                $this->log('Unknown market websocket event type:', $eventType, $message);
            }
        }
    }

    public function handle_user_event(Client $client, mixed $message, string $eventType) {
        if ($eventType === 'order') {
            $this->handle_orders($client, $message);
        } elseif ($eventType === 'trade') {
            $this->handle_my_trades($client, $message);
        } else {
            // Unknown event type, log but don't error
            if ($this->verbose) {
                $this->log('Unknown user websocket event type:', $eventType, $message);
            }
        }
    }

    public function handle_new_market(Client $client, $message) {
        // Handle new market event
        // Docs => https://docs.polymarket.com/developers/CLOB/websocket/market-channel#new_market-$message
        $marketData = $this->safe_dict($message, 'market', array());
        $marketId = $this->safe_string($marketData, 'id');
        if ($marketId) {
            // Update marketUpdates cache
            if (!$this->marketUpdates) {
                $this->marketUpdates = array();
            }
            $this->marketUpdates[$marketId] = array(
                'event_type' => 'new_market',
                'market' => $marketData,
            );
            $client->resolve ($this->marketUpdates, 'markets');
        }
    }

    public function handle_market_resolved(Client $client, $message) {
        // Handle market resolved event
        // Docs => https://docs.polymarket.com/developers/CLOB/websocket/market-channel#market_resolved-$message
        $marketData = $this->safe_dict($message, 'market', array());
        $marketId = $this->safe_string($marketData, 'id');
        if ($marketId) {
            // Update marketUpdates cache
            if (!$this->marketUpdates) {
                $this->marketUpdates = array();
            }
            $this->marketUpdates[$marketId] = array(
                'event_type' => 'market_resolved',
                'market' => $marketData,
            );
            $client->resolve ($this->marketUpdates, 'markets');
        }
    }

    public function authenticate($params = array ()) {
        return Async\async(function () use ($params) {
            $url = $this->urls['api']['ws']['user'];
            $client = $this->client($url);
            $messageHash = 'authenticated';
            $future = $this->safe_value($client->subscriptions, $messageHash);
            if ($future === null) {
                // Get API credentials
                $creds = Async\await($this->ensureApiCredentials ($params));
                // Build $auth payload matching Python implementation
                // $auth=$creds->model_dump(is_array(Python becomes:
                $auth = array(
                    'apiKey' => $creds['apiKey'],
                    'secret' => $creds['secret'],
                    'passphrase' => $creds['passphrase'],
                ) && array_key_exists(by_alias=True), Python becomes:
                $auth = array(
                    'apiKey' => $creds['apiKey'],
                    'secret' => $creds['secret'],
                    'passphrase' => $creds['passphrase'],
                ));
                $request = array(
                    'auth' => $auth,
                    'type' => $this->options['wsUserChannelType'],
                );
                $future = Async\await($this->watch($url, $messageHash, $request, $messageHash));
                $client->subscriptions[$messageHash] = $future;
            }
            return $future;
        }) ();
    }

    public function watch(string $url, string $messageHash, $message = null, $subscribeHash = null, $subscription = null) {
        return Async\async(function () use ($url, $messageHash, $message, $subscribeHash, $subscription) {
            $client = $this->client($url);
            if ($subscribeHash === null) {
                $subscribeHash = $messageHash;
            }
            // Handle market channel subscriptions with dynamic subscribe/unsubscribe (following onetrading pattern)
            if ($subscription !== null && mb_strpos($url, '/ws/market') !== false) {
                // Use wsMarketChannelType for $subscription hash
                $channelSubscriptionHash = $this->options['wsMarketChannelType'];
                // Extract asset_id from $message or $subscription
                $assetId => string | null = null;
                if ($message && gettype($message) === 'array') {
                    $assetsIds = $this->safe_value($message, 'assets_ids', array());
                    if ((gettype($assetsIds) === 'array' && array_keys($assetsIds) === array_keys(array_keys($assetsIds))) && strlen($assetsIds) > 0) {
                        $assetId = $this->safe_string($assetsIds, 0);
                    }
                }
                if ($assetId === null) {
                    $assetId = $this->safe_string_2($subscription, 'asset_id', 'token_id');
                }
                if ($assetId !== null) {
                    // Get existing $subscription or create new one
                    $channelSubscription = $this->safe_value($client->subscriptions, $channelSubscriptionHash, array());
                    if (gettype($channelSubscription) !== 'array' || (gettype($channelSubscription) === 'array' && array_keys($channelSubscription) === array_keys(array_keys($channelSubscription)))) {
                        $channelSubscription = array();
                    }
                    // Check if we're already connected
                    $isConnected = $client->connection && $client->connection.readyState === 1; // WebSocket.OPEN = 1
                    // Check if asset_id needs to be added
                    $needsSubscribe = !(is_array($channelSubscription) && array_key_exists($assetId, $channelSubscription));
                    if ($isConnected && $needsSubscribe) {
                        // Connection exists and asset_id not subscribed - use dynamic subscribe
                        Async\await($this->subscribe_to_asset_ids(array( $assetId )));
                    }
                    // Add asset_id to $subscription tracking
                    $channelSubscription[$assetId] = true;
                    $client->subscriptions[$channelSubscriptionHash] = $channelSubscription;
                    // Build $message with all subscribed asset_ids (following onetrading pattern)
                    $allAssetIds = is_array($channelSubscription) ? array_keys($channelSubscription) : array();
                    if ($message && gettype($message) === 'array') {
                        $message['assets_ids'] = $allAssetIds;
                        $message['type'] = $this->options['wsMarketChannelType'];
                    }
                    // Store individual $subscription info for $message routing
                    if (!(is_array($client->subscriptions) && array_key_exists($subscribeHash, $client->subscriptions))) {
                        $client->subscriptions[$subscribeHash] = $subscription;
                    }
                }
            }
            return Async\await(parent::watch($url, $messageHash, $message, $subscribeHash, $subscription));
        }) ();
    }

    public function subscribe_to_asset_ids(array $asset_ids, $params = array ()) {
        return Async\async(function () use ($asset_ids, $params) {
            /**
             * Dynamically subscribe to additional asset IDs on an existing market channel connection
             * @param {string[]} $asset_ids list of asset IDs to subscribe to
             * @param {array} [$params] extra parameters
             * @return array(Promise<void>)
             */
            $url = $this->urls['api']['ws']['market'];
            $client = $this->client($url);
            if (!($client->connection && $client->connection.readyState === 1)) {
                throw new ExchangeError($this->id . ' subscribeToAssetIds() requires an active WebSocket connection');
            }
            $channelSubscriptionHash = $this->options['wsMarketChannelType'];
            $channelSubscription = $this->safe_value($client->subscriptions, $channelSubscriptionHash, array());
            if (gettype($channelSubscription) !== 'array' || (gettype($channelSubscription) === 'array' && array_keys($channelSubscription) === array_keys(array_keys($channelSubscription)))) {
                $channelSubscription = array();
            }
            // Filter out already subscribed $asset_ids
            $newAssetIds = array()
            for ($i = 0; $i < count($asset_ids); $i++) {
                $aid = $asset_ids[$i];
                if (!(is_array($channelSubscription) && array_key_exists($aid, $channelSubscription))) {
                    $newAssetIds[] = $aid;
                }
            }
            if (strlen($newAssetIds) === 0) {
                return; // All already subscribed
            }
            $request = array(
                'assets_ids' => $newAssetIds,
                'operation' => 'subscribe',
            );
            Async\await($client->send ($request));
            // Track newly subscribed $asset_ids
            for ($i = 0; $i < count($newAssetIds); $i++) {
                $aid = $newAssetIds[$i];
                $channelSubscription[$aid] = true;
            }
            $client->subscriptions[$channelSubscriptionHash] = $channelSubscription;
        }) ();
    }

    public function unsubscribe_from_asset_ids(array $asset_ids, $params = array ()) {
        return Async\async(function () use ($asset_ids, $params) {
            /**
             * Dynamically unsubscribe from asset IDs on an existing market channel connection
             * @param {string[]} $asset_ids list of asset IDs to unsubscribe from
             * @param {array} [$params] extra parameters
             * @return array(Promise<void>)
             */
            $url = $this->urls['api']['ws']['market'];
            $client = $this->client($url);
            if (!($client->connection && $client->connection.readyState === 1)) {
                throw new ExchangeError($this->id . ' unsubscribeFromAssetIds() requires an active WebSocket connection');
            }
            $channelSubscriptionHash = $this->options['wsMarketChannelType'];
            $channelSubscription = $this->safe_value($client->subscriptions, $channelSubscriptionHash, array());
            if (gettype($channelSubscription) !== 'array' || (gettype($channelSubscription) === 'array' && array_keys($channelSubscription) === array_keys(array_keys($channelSubscription)))) {
                $channelSubscription = array();
            }
            // Filter to only unsubscribe from actually subscribed $asset_ids
            $subscribedAssetIds = array()
            for ($i = 0; $i < count($asset_ids); $i++) {
                $aid = $asset_ids[$i];
                if (is_array($channelSubscription) && array_key_exists($aid, $channelSubscription)) {
                    $subscribedAssetIds[] = $aid;
                }
            }
            if (strlen($subscribedAssetIds) === 0) {
                return; // None are subscribed
            }
            $request = array()
            $request['assets_ids'] = $subscribedAssetIds;
            $request['operation'] = 'unsubscribe';
            Async\await($client->send ($request));
            // Remove from tracking
            for ($i = 0; $i < count($subscribedAssetIds); $i++) {
                $aid = $subscribedAssetIds[$i];
                unset($channelSubscription[$aid]);
            }
            $client->subscriptions[$channelSubscriptionHash] = $channelSubscription;
        }) ();
    }

    public function on_connected(Client $client) {
        // Called when websocket connection is established
        // The base watch() method will send the message automatically
        // The message parameter passed to watch() is sent when the connection opens
        // This is equivalent to the on_open handler in the example code
        parent::on_connected($client);
    }
}
